(function()
	_G.pg.base.gametip.help_music_game = {
		tip = {
			{
				info = "- Manjuu Karaoke Lounge Overview -\n\nThe Manjuu Karaoke Lounge is a rhythm mini-game where you can earn Performance Notes.\nWhen you get a B or higher rating in the minigame, you will use up a reward attempt and earn a Performance Note. Collect 7 to get the event-exclusive item, Harmony μ Ticket.\nYou can earn one Performance Note per day after the event starts, up to 7 total.\n- How to Play -\n· Select a song from the song selection slider, and select a desired difficulty level. You will earn points for tapping an icon when it arrives at the center of the screen.\n· On Hard difficulty, tap the left side of the screen when a blue icon shows up, tap the right side when a red icon shows up, and tap both sides when a yellow icon shows up. If an icon is followed by a white trail, you need to tap and hold the corresponding side of the screen until it ends. If you release the hold before the white trail ends, you will only score a Good rating.\n· The \"\"X1\"\" button on the top-right hand side of the screen indicates the current note speed. Tap the button to toggle your note speed.\n· The rating and score you receive for each tapped note corresponds to your timing.\n· Your Combo will only increase for taps that score a Good or Perfect rating."
			}
		}
	}
end)()

(function()
	_G.pg.base.gametip.littleChaijun_npc = {
		tip = {
			{
				info = "- Overview -\nDuring the event, Little Cheshire will provisionally join your fleet. Complete missions to earn Cookie Pts and earn Trust. Collect enough Trust to have Little Cheshire permanently join your fleet!"
			},
			{
				info = "- How to Play -\n· During the event period, completing the A Cookie For Mew! event missions will reward you with Cookie Pts. These will be automatically converted into Trust. Accumulating certain amounts of Trust will grant you additional rewards."
			},
			{
				info = "· You will not be able to give a Promise Ring to Little Cheshire until you have formally recruited her to the fleet. You will also not be able to Retire her or use her as Enhancement or Limit Break material."
			},
			{
				info = "· If Little Cheshire has not been formally recruited by the end of the event, she will leave the Port."
			},
			{
				info = "· Rewards for reaching certain amounts of Trust will unlock in phases, one phase per day up to April 17th."
			},
			{
				info = "· Little Cheshire cannot participate in Operation Siren or META Showdowns until she has been formally recruited."
			},
			{
				info = "· Little Cheshire cannot participate in Guild Bosses until she has been formally recruited."
			}
		}
	}
end)()

