(function()
	_G.pg.base.gametip.xiaodadi_npc = {
		tip = {
			{
				info = "- Overview -"
			},
			{
				info = "During the event, Little Friedrich will provisionally join your fleet. Complete missions during the event to earn Trust. Collect enough Trust to have Little Friedrich permanently join your fleet!"
			},
			{
				info = "- How to Play -"
			},
			{
				info = "· During the event period, you can earn Trust by defeating the boss fleet in stages at or after Chapter 3 of the Campaign, or in event stages (excluding War Archives). You will be able to unlock rewards by reaching certain Trust milestones."
			},
			{
				info = "· When you defeat the boss of a stage that rewards Trust, you will earn twice as many Trust if Little Friedrich is still afloat in one of the fleets at that time."
			},
			{
				info = "· You will not be able to give a Promise Ring to Little Friedrich until you have formally recruited her to the fleet.You will also not be able to Retireor use her as Enhancement or Limit Break material."
			},
			{
				info = "· If Little Friedrich has not been formally recruited by the end of the event, she will leave the Port."
			},
			{
				info = "· Rewards for reaching certain amounts of Trust will unlock in phases, one phase per day until June 5th."
			},
			{
				info = "· Little Friedrich cannot participate in Operation Siren or META Showdowns until she has been formally recruited."
			},
			{
				info = "· Little Friedrich cannot participate in Guild Bosses until she has been formally recruited."
			}
		}
	}
end)()

(function()
	_G.pg.base.gametip.help_chunjie2023 = {
		tip = {
			{
				info = "Events last from <color=#92fc63>January 18th to February 1st</color>\n\n- Spring Festival Overview -\n· <color=#92fc63>Fu Shun's Great Adventure IV</color> - play the minigame over 7 days to unlock the destroyer <color=#92fc63>Fu Shun</color>.\n· <color=#92fc63>Spring Blossoms</color> - clear Chapter 3+ stages to earn Festive Shooting Stars and unlock the seaplane carrier <color=#92fc63>Ting An</color>.\n· <color=#92fc63>Inside the Painting</color> - complete the minigame to unlock the light cruisers <color=#92fc63>Hai Chi</color> and <color=#92fc63>Hai Tien</color>.\n· <color=#92fc63>Drawing Book</color> - clear Chapter 3+ stages to earn Pigments and unlock the destroyer <color=#92fc63>An Shan</color>.\n· <color=#92fc63>Songs of Spring</color> - complete daily missions and finish the songs to unlock an exclusive piece of gear for Yat Sen.\n· <color=#92fc63>Manjuu Resort</color> - open the Red Envelopes you've collected through minigames and mini-events. Open a total of 15 to receive U-73's <color=#92fc63>New Year's Chemistry</color> skin and open 25 to receive Fu Shun's <color=#92fc63>The Unbreakable Baozi Heist</color> skin.\n· <color=#92fc63>New Skins</color> - visit the skins shop and see the latest fashion on offer.\n· <color=#92fc63>Limited Construction</color> - go to the build menu and recruit new shipgirls."
			}
		}
	}
end)()

